-- seed-flats.sql — 12 core blanks as owned templates (flat-gen/1).
-- Generated by scripts/seed-flats.ts. Re-runnable. Apply to the LOCAL
-- database only (psql -f seed-flats.sql). SVGs live in --svg-dir;
-- upload them to design-private at the storage_path recorded here
-- (the --supabase mode does that + the inserts in one step).
-- tenant 11111111-1111-4111-8111-111111111111, base size M
BEGIN;
DO $$ DECLARE lic uuid; BEGIN
  SELECT id INTO lic FROM public.ds_asset_licenses WHERE tenant_id = '11111111-1111-4111-8111-111111111111' AND source = 'generated' AND license_type = 'owned' ORDER BY created_at LIMIT 1;
  IF lic IS NULL THEN
    INSERT INTO public.ds_asset_licenses(tenant_id, source, license_type, license_name, allow_supplier_view, allow_redistribution)
    VALUES ('11111111-1111-4111-8111-111111111111', 'generated', 'owned', 'Atelier owned flat', true, false) RETURNING id INTO lic;
  END IF;
  PERFORM set_config('seed_flats.owned_license', lic::text, true);
END $$;
DO $$ DECLARE lic uuid := current_setting('seed_flats.owned_license')::uuid; front_asset uuid; BEGIN
  INSERT INTO public.design_assets(tenant_id, kind, storage_path, bucket, classification, mime_type, license_id, metadata)
  SELECT '11111111-1111-4111-8111-111111111111', 'flat_sketch', '11111111-1111-4111-8111-111111111111/library/flats/classic-tee/front.svg', 'design-private', 'internal', 'image/svg+xml', lic, '{"blank_id":"classic-tee","view":"front","size":"M","generator_version":"flat-gen/1"}'::jsonb
  WHERE NOT EXISTS (SELECT 1 FROM public.design_assets WHERE storage_path = '11111111-1111-4111-8111-111111111111/library/flats/classic-tee/front.svg');
